    // Compare this with find(), which treats nonexistent indexes as undefined:
    const arr2 = ["e1", "e2", "e3", "e4"];
    arr2.find((elem, index, arr) => {
      console.log(`array: [${arr.join(", ")}], index: ${index}, elem: ${elem}`);
      if (index === 1) arr.splice(2, 1);
