#####  Auto-configured Spring REST Docs Tests With REST Assured

` @AutoConfigureRestDocs ` makes a ` RequestSpecification ` bean,
preconfigured to use Spring REST Docs, available to your tests. You can inject
it by using ` @Autowired ` and use it in your tests as you normally would when
using REST Assured and Spring REST Docs, as shown in the following example:

Java



    import io.restassured.specification.RequestSpecification;
    import org.junit.jupiter.api.Test;

    import org.springframework.beans.factory.annotation.Autowired;
    import org.springframework.boot.test.autoconfigure.restdocs.AutoConfigureRestDocs;
    import org.springframework.boot.test.context.SpringBootTest;
    import org.springframework.boot.test.context.SpringBootTest.WebEnvironment;
    import org.springframework.boot.test.web.server.LocalServerPort;

    import static io.restassured.RestAssured.given;
    import static org.hamcrest.Matchers.is;
    import static org.springframework.restdocs.restassured.RestAssuredRestDocumentation.document;

    @SpringBootTest(webEnvironment = WebEnvironment.RANDOM_PORT)
    @AutoConfigureRestDocs
    class MyUserDocumentationTests {

        @Test
        void listUsers(@Autowired RequestSpecification documentationSpec, @LocalServerPort int port) {
            given(documentationSpec)
                .filter(document("list-users"))
            .when()
                .port(port)
                .get("/")
            .then().assertThat()
                .statusCode(is(200));
        }

    }


